import{_ as t,c as d,o,ae as r}from"./chunks/framework.DCU7Csu6.js";const u=JSON.parse('{"title":"Epic 26: DBS Module - New Endpoints (February 2026 Swagger Update)","description":"","frontmatter":{},"headers":[],"relativePath":"epics/EPIC_26_DBS_NEW_ENDPOINTS.md","filePath":"epics/EPIC_26_DBS_NEW_ENDPOINTS.md"}'),a={name:"epics/EPIC_26_DBS_NEW_ENDPOINTS.md"};function i(s,e,n,l,c,p){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="epic-26-dbs-module-new-endpoints-february-2026-swagger-update" tabindex="-1">Epic 26: DBS Module - New Endpoints (February 2026 Swagger Update) <a class="header-anchor" href="#epic-26-dbs-module-new-endpoints-february-2026-swagger-update" aria-label="Permalink to &quot;Epic 26: DBS Module - New Endpoints (February 2026 Swagger Update)&quot;">​</a></h1><p><strong>Epic Goal</strong>: Add 9 new DBS endpoints discovered in the February 2026 swagger update: 2 entirely new info endpoints and 7 bulk metadata endpoints that replace deprecated single-order metadata methods.</p><p><strong>Target Completion</strong>: Epic 26.x (Stories 26.1-26.2) <strong>SDK Version</strong>: 2.9.0 <strong>Status</strong>: DONE</p><p><strong>Business Value</strong>:</p><ul><li>2 new info endpoints enable paid delivery group management and delivery date retrieval</li><li>7 bulk metadata endpoints replace deprecated single-order methods scheduled for removal on April 13, 2026</li><li>Prevents SDK breakage when deprecated endpoints are disabled</li><li>Bulk metadata operations improve throughput for sellers processing high order volumes</li><li>Adds ~19 new TypeScript schemas for complete type safety</li></ul><hr><h2 id="epic-26-overview" tabindex="-1">Epic 26 Overview <a class="header-anchor" href="#epic-26-overview" aria-label="Permalink to &quot;Epic 26 Overview&quot;">​</a></h2><h3 id="strategic-context" tabindex="-1">Strategic Context <a class="header-anchor" href="#strategic-context" aria-label="Permalink to &quot;Strategic Context&quot;">​</a></h3><p>The February 2026 swagger update for the DBS API introduced 9 new endpoints that were not present when Epic 12 was authored. The DBS module now has <strong>31 total operations</strong>: 19 active and 12 deprecated.</p><p>The SDK currently implements <strong>22 methods</strong> (from Epic 12), but 7 of those methods call deprecated single-order metadata endpoints (<code>GET /api/v3/dbs/orders/{orderId}/meta</code>, <code>DELETE /api/v3/dbs/orders/{orderId}/meta</code>, and 5 <code>PUT /api/v3/dbs/orders/{orderId}/meta/*</code> routes). These deprecated endpoints are scheduled for removal on <strong>April 13, 2026</strong>. The new bulk metadata endpoints at <code>/api/marketplace/v3/dbs/orders/meta/*</code> accept arrays of order IDs and must replace the current implementations.</p><p><strong>Active vs Deprecated Endpoint Summary</strong>:</p><table tabindex="0"><thead><tr><th>Category</th><th>Active</th><th>Deprecated</th><th>SDK Methods</th><th>Status</th></tr></thead><tbody><tr><td>Core Operations (12.1)</td><td>3</td><td>0</td><td>3</td><td>Complete</td></tr><tr><td>Bulk Status (12.2)</td><td>6</td><td>0</td><td>6</td><td>Complete</td></tr><tr><td>Legacy Status (12.2)</td><td>0</td><td>6</td><td>6</td><td>Complete (deprecated)</td></tr><tr><td>Metadata (12.3)</td><td>0</td><td>7</td><td>7</td><td><strong>Must migrate</strong></td></tr><tr><td>B2B (12.4)</td><td>1</td><td>0</td><td>1</td><td>Complete</td></tr><tr><td>New Info (this epic)</td><td>2</td><td>0</td><td>0</td><td><strong>Must add</strong></td></tr><tr><td>New Bulk Meta (this epic)</td><td>7</td><td>0</td><td>0</td><td><strong>Must add</strong></td></tr><tr><td><strong>Totals</strong></td><td><strong>19</strong></td><td><strong>12</strong> (1 status + 5 status + 6 meta from April)</td><td><strong>22</strong></td><td></td></tr></tbody></table><h3 id="technical-context" tabindex="-1">Technical Context <a class="header-anchor" href="#technical-context" aria-label="Permalink to &quot;Technical Context&quot;">​</a></h3><p><strong>Swagger Source</strong>: <code>wildberries_api_doc/04-orders-dbs/</code> (4 shard files) <strong>Module File</strong>: <code>src/modules/orders-dbs/index.ts</code> (714 lines) <strong>Types File</strong>: <code>src/types/orders-dbs.types.ts</code><strong>Rate Limit Config</strong>: <code>src/config/orders-dbs-rate-limits.ts</code> (201 lines) <strong>Base URL</strong>: <code>https://marketplace-api.wildberries.ru</code></p><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><p><strong>Depends On:</strong></p><ul><li>Epic 12 Complete - DBS module foundation (all stories 12.1-12.5)</li><li>Epic 27 - Rate limit audit should be completed first or in parallel (rate limit keys must be correct before adding new entries)</li></ul><p><strong>Blocks:</strong></p><ul><li>Any future DBS module maintenance or extension</li></ul><hr><h2 id="new-endpoints-detail" tabindex="-1">New Endpoints Detail <a class="header-anchor" href="#new-endpoints-detail" aria-label="Permalink to &quot;New Endpoints Detail&quot;">​</a></h2><h3 id="group-1-new-info-endpoints-story-26-1" tabindex="-1">Group 1: New Info Endpoints (Story 26.1) <a class="header-anchor" href="#group-1-new-info-endpoints-story-26-1" aria-label="Permalink to &quot;Group 1: New Info Endpoints (Story 26.1)&quot;">​</a></h3><p>Two entirely new endpoints with no deprecated predecessors.</p><table tabindex="0"><thead><tr><th>#</th><th>Method</th><th>Path</th><th>Description</th><th>Request Type</th><th>Response Type</th></tr></thead><tbody><tr><td>1</td><td><code>POST</code></td><td><code>/api/v3/dbs/groups/info</code></td><td>Get paid delivery groups</td><td><code>api.OrderGroupsRequest</code></td><td><code>api.OrderGroup[]</code></td></tr><tr><td>2</td><td><code>POST</code></td><td><code>/api/v3/dbs/orders/delivery-date</code></td><td>Get delivery dates for orders</td><td><code>DeliveryDatesRequest</code></td><td><code>DeliveryDatesInfoResp</code></td></tr></tbody></table><p><strong>Rate Limits</strong>: Standard DBS read tier -- 300 req/min, 200ms interval, 20 burst</p><p><strong>SDK Method Names</strong>:</p><ul><li><code>getGroupsInfo(request: OrderGroupsRequest): Promise&lt;OrderGroupsResponse&gt;</code></li><li><code>getDeliveryDates(request: DeliveryDatesRequest): Promise&lt;DeliveryDatesInfoResponse&gt;</code></li></ul><h3 id="group-2-bulk-metadata-migration-story-26-2" tabindex="-1">Group 2: Bulk Metadata Migration (Story 26.2) <a class="header-anchor" href="#group-2-bulk-metadata-migration-story-26-2" aria-label="Permalink to &quot;Group 2: Bulk Metadata Migration (Story 26.2)&quot;">​</a></h3><p>Seven new bulk POST endpoints replacing the deprecated single-order metadata methods. All accept arrays of order IDs for batch processing.</p><table tabindex="0"><thead><tr><th>#</th><th>New Bulk Endpoint</th><th>Replaces Deprecated Endpoint</th><th>Operation</th></tr></thead><tbody><tr><td>1</td><td><code>POST /api/marketplace/v3/dbs/orders/meta/info</code></td><td><code>GET /api/v3/dbs/orders/{orderId}/meta</code></td><td>Get metadata (bulk)</td></tr><tr><td>2</td><td><code>POST /api/marketplace/v3/dbs/orders/meta/delete</code></td><td><code>DELETE /api/v3/dbs/orders/{orderId}/meta</code></td><td>Delete metadata (bulk)</td></tr><tr><td>3</td><td><code>POST /api/marketplace/v3/dbs/orders/meta/sgtin</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/sgtin</code></td><td>Set SGTIN (bulk)</td></tr><tr><td>4</td><td><code>POST /api/marketplace/v3/dbs/orders/meta/uin</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/uin</code></td><td>Set UIN (bulk)</td></tr><tr><td>5</td><td><code>POST /api/marketplace/v3/dbs/orders/meta/imei</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/imei</code></td><td>Set IMEI (bulk)</td></tr><tr><td>6</td><td><code>POST /api/marketplace/v3/dbs/orders/meta/gtin</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/gtin</code></td><td>Set GTIN (bulk)</td></tr><tr><td>7</td><td><code>POST /api/marketplace/v3/dbs/orders/meta/customs-declaration</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/customs-declaration</code></td><td>Set customs declaration (bulk)</td></tr></tbody></table><p><strong>Rate Limits</strong>:</p><table tabindex="0"><thead><tr><th>Operation Type</th><th>Limit</th><th>Interval</th><th>Burst</th></tr></thead><tbody><tr><td>Read (<code>meta/info</code>)</td><td>150 req/min</td><td>400ms</td><td>20</td></tr><tr><td>Delete (<code>meta/delete</code>)</td><td>150 req/min</td><td>400ms</td><td>20</td></tr><tr><td>Set (<code>meta/sgtin</code>, <code>meta/uin</code>, <code>meta/imei</code>, <code>meta/gtin</code>, <code>meta/customs-declaration</code>)</td><td>500 req/min</td><td>120ms</td><td>20</td></tr></tbody></table><p><strong>SDK Method Names (Bulk)</strong>:</p><ul><li><code>getMetaBulk(orderIds: number[]): Promise&lt;GetOrderMetaBulkResponse&gt;</code></li><li><code>deleteMetaBulk(request: DeleteMetaBulkRequest): Promise&lt;DeleteMetaBulkResponse&gt;</code></li><li><code>setSgtinBulk(request: SetSgtinBulkRequest): Promise&lt;SetMetaBulkResponse&gt;</code></li><li><code>setUinBulk(request: SetUinBulkRequest): Promise&lt;SetMetaBulkResponse&gt;</code></li><li><code>setImeiBulk(request: SetImeiBulkRequest): Promise&lt;SetMetaBulkResponse&gt;</code></li><li><code>setGtinBulk(request: SetGtinBulkRequest): Promise&lt;SetMetaBulkResponse&gt;</code></li><li><code>setCustomsDeclarationBulk(request: SetCustomsDeclarationBulkRequest): Promise&lt;SetMetaBulkResponse&gt;</code></li></ul><p><strong>Migration Strategy</strong>:</p><ol><li>Add new bulk methods alongside existing single-order methods</li><li>Mark existing single-order metadata methods (<code>getMeta</code>, <code>deleteMeta</code>, <code>setSgtin</code>, <code>setUin</code>, <code>setImei</code>, <code>setGtin</code>, <code>setCustomsDeclaration</code>) with <code>@deprecated</code> JSDoc</li><li>Add deprecation warning pointing to the bulk replacement</li><li>Existing single-order methods remain functional until WB disables the endpoints (April 13, 2026)</li></ol><hr><h2 id="new-schemas" tabindex="-1">New Schemas <a class="header-anchor" href="#new-schemas" aria-label="Permalink to &quot;New Schemas&quot;">​</a></h2><p>Approximately 19 new TypeScript schemas required from swagger components:</p><p><strong>Info Endpoint Schemas</strong>:</p><ul><li><code>OrderGroupsRequest</code> - Request body for groups/info</li><li><code>OrderGroup</code> - Paid delivery group info</li><li><code>OrderGroupsResponse</code> - Response wrapper for groups/info</li><li><code>DeliveryDatesRequest</code> - Request body for delivery-date</li><li><code>DeliveryDateInfo</code> - Single order delivery date record</li><li><code>DeliveryDatesInfoResponse</code> - Response wrapper for delivery-date</li></ul><p><strong>Bulk Metadata Schemas</strong>:</p><ul><li><code>GetMetaBulkRequest</code> - Request body for meta/info</li><li><code>GetOrderMetaBulkResponse</code> - Response with metadata per order</li><li><code>BulkOrderMeta</code> - Single order metadata record in bulk response</li><li><code>DeleteMetaBulkRequest</code> - Request body for meta/delete (orderIds + key)</li><li><code>DeleteMetaBulkResponse</code> - Response for bulk delete</li><li><code>SetSgtinBulkRequest</code> - Bulk SGTIN set request (order ID + sgtins array per item)</li><li><code>SetUinBulkRequest</code> - Bulk UIN set request</li><li><code>SetImeiBulkRequest</code> - Bulk IMEI set request</li><li><code>SetGtinBulkRequest</code> - Bulk GTIN set request</li><li><code>SetCustomsDeclarationBulkRequest</code> - Bulk customs declaration set request</li><li><code>SetMetaBulkResponse</code> - Shared response type for all bulk set operations</li><li><code>BulkMetaResultItem</code> - Per-order result in bulk response (orderId, success, error)</li><li><code>BulkMetaError</code> - Error detail for individual order failures</li></ul><hr><h2 id="story-breakdown" tabindex="-1">Story Breakdown <a class="header-anchor" href="#story-breakdown" aria-label="Permalink to &quot;Story Breakdown&quot;">​</a></h2><h3 id="story-26-1-new-info-endpoints-high" tabindex="-1">Story 26.1: New Info Endpoints (HIGH) <a class="header-anchor" href="#story-26-1-new-info-endpoints-high" aria-label="Permalink to &quot;Story 26.1: New Info Endpoints (HIGH)&quot;">​</a></h3><p><strong>Priority</strong>: HIGH - New functionality not available in current SDK <strong>Estimated Complexity</strong>: LOW <strong>Story Points</strong>: 3</p><p><strong>Description</strong>: Implement 2 new info endpoints for paid delivery groups and delivery dates.</p><p><strong>Endpoints</strong>:</p><ul><li><code>POST /api/v3/dbs/groups/info</code> -- Get paid delivery groups</li><li><code>POST /api/v3/dbs/orders/delivery-date</code> -- Get delivery dates for orders</li></ul><p><strong>Acceptance Criteria</strong>:</p><ol><li><code>getGroupsInfo()</code> implemented with proper request/response types</li><li><code>getDeliveryDates()</code> implemented with proper request/response types</li><li>All new schemas added to <code>src/types/orders-dbs.types.ts</code></li><li>Rate limit entries added to <code>src/config/orders-dbs-rate-limits.ts</code></li><li>Rate limit keys in config match <code>rateLimitKey</code> values in module code</li><li>Unit tests with &gt;= 80% coverage</li><li>Integration tests with MSW</li><li>JSDoc documentation with examples</li></ol><p><strong>Files Modified</strong>:</p><ul><li><code>src/modules/orders-dbs/index.ts</code> -- Add 2 new methods</li><li><code>src/types/orders-dbs.types.ts</code> -- Add ~6 new schemas</li><li><code>src/config/orders-dbs-rate-limits.ts</code> -- Add 2 new rate limit entries</li></ul><hr><h3 id="story-26-2-bulk-metadata-migration-critical" tabindex="-1">Story 26.2: Bulk Metadata Migration (CRITICAL) <a class="header-anchor" href="#story-26-2-bulk-metadata-migration-critical" aria-label="Permalink to &quot;Story 26.2: Bulk Metadata Migration (CRITICAL)&quot;">​</a></h3><p><strong>Priority</strong>: CRITICAL - Deprecated endpoints removed April 13, 2026 <strong>Estimated Complexity</strong>: MEDIUM <strong>Story Points</strong>: 8</p><p><strong>Description</strong>: Implement 7 new bulk metadata endpoints and mark existing single-order metadata methods as deprecated. The current SDK methods <code>getMeta()</code>, <code>deleteMeta()</code>, <code>setSgtin()</code>, <code>setUin()</code>, <code>setImei()</code>, <code>setGtin()</code>, and <code>setCustomsDeclaration()</code> all call deprecated single-order endpoints that will be disabled on April 13, 2026.</p><p><strong>Endpoints</strong>:</p><ul><li><code>POST /api/marketplace/v3/dbs/orders/meta/info</code> -- Get metadata (bulk)</li><li><code>POST /api/marketplace/v3/dbs/orders/meta/delete</code> -- Delete metadata (bulk)</li><li><code>POST /api/marketplace/v3/dbs/orders/meta/sgtin</code> -- Set SGTIN (bulk)</li><li><code>POST /api/marketplace/v3/dbs/orders/meta/uin</code> -- Set UIN (bulk)</li><li><code>POST /api/marketplace/v3/dbs/orders/meta/imei</code> -- Set IMEI (bulk)</li><li><code>POST /api/marketplace/v3/dbs/orders/meta/gtin</code> -- Set GTIN (bulk)</li><li><code>POST /api/marketplace/v3/dbs/orders/meta/customs-declaration</code> -- Set customs declaration (bulk)</li></ul><p><strong>Rate Limit Tiers</strong>:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Limit</th><th>Interval</th><th>Burst</th></tr></thead><tbody><tr><td>Read/delete (<code>meta/info</code>, <code>meta/delete</code>)</td><td>150 req/min</td><td>400ms</td><td>20</td></tr><tr><td>Set (<code>meta/sgtin</code>, <code>meta/uin</code>, <code>meta/imei</code>, <code>meta/gtin</code>, <code>meta/customs-declaration</code>)</td><td>500 req/min</td><td>120ms</td><td>20</td></tr></tbody></table><p><strong>Acceptance Criteria</strong>:</p><ol><li>7 new bulk metadata methods implemented (<code>getMetaBulk</code>, <code>deleteMetaBulk</code>, <code>setSgtinBulk</code>, <code>setUinBulk</code>, <code>setImeiBulk</code>, <code>setGtinBulk</code>, <code>setCustomsDeclarationBulk</code>)</li><li>All new schemas added to <code>src/types/orders-dbs.types.ts</code> (~13 schemas)</li><li>Rate limit entries added with correct tier values (150/min for read/delete, 500/min for set)</li><li>Rate limit keys in config match <code>rateLimitKey</code> values in module code</li><li>Existing single-order methods (<code>getMeta</code>, <code>deleteMeta</code>, <code>setSgtin</code>, <code>setUin</code>, <code>setImei</code>, <code>setGtin</code>, <code>setCustomsDeclaration</code>) marked with <code>@deprecated</code> JSDoc pointing to bulk replacement</li><li>Input validation for all bulk methods (array bounds, field constraints)</li><li>Unit tests with &gt;= 80% coverage for all 7 new methods</li><li>Integration tests with MSW covering bulk workflows</li><li>Migration guide from single-order to bulk metadata methods</li><li>JSDoc documentation with examples for all new methods</li></ol><p><strong>Files Modified</strong>:</p><ul><li><code>src/modules/orders-dbs/index.ts</code> -- Add 7 new methods, deprecate 7 existing methods</li><li><code>src/types/orders-dbs.types.ts</code> -- Add ~13 new schemas</li><li><code>src/config/orders-dbs-rate-limits.ts</code> -- Add 7 new rate limit entries with correct tiers</li></ul><hr><h2 id="implementation-strategy" tabindex="-1">Implementation Strategy <a class="header-anchor" href="#implementation-strategy" aria-label="Permalink to &quot;Implementation Strategy&quot;">​</a></h2><h3 id="phase-1-info-endpoints-story-26-1" tabindex="-1">Phase 1: Info Endpoints (Story 26.1) <a class="header-anchor" href="#phase-1-info-endpoints-story-26-1" aria-label="Permalink to &quot;Phase 1: Info Endpoints (Story 26.1)&quot;">​</a></h3><p><strong>Timeline</strong>: 1-2 days <strong>Focus</strong>: New functionality with no migration concerns <strong>Dependencies</strong>: Epic 12 complete</p><h3 id="phase-2-bulk-metadata-migration-story-26-2" tabindex="-1">Phase 2: Bulk Metadata Migration (Story 26.2) <a class="header-anchor" href="#phase-2-bulk-metadata-migration-story-26-2" aria-label="Permalink to &quot;Phase 2: Bulk Metadata Migration (Story 26.2)&quot;">​</a></h3><p><strong>Timeline</strong>: 3-4 days <strong>Focus</strong>: Add bulk methods, deprecate single-order methods, write migration guide <strong>Dependencies</strong>: Story 26.1 complete (or can run in parallel)</p><p><strong>Total Epic 26 Duration</strong>: ~4-6 days</p><hr><h2 id="api-methods-summary-post-epic-26" tabindex="-1">API Methods Summary (Post-Epic 26) <a class="header-anchor" href="#api-methods-summary-post-epic-26" aria-label="Permalink to &quot;API Methods Summary (Post-Epic 26)&quot;">​</a></h2><h3 id="new-methods-added" tabindex="-1">New Methods Added <a class="header-anchor" href="#new-methods-added" aria-label="Permalink to &quot;New Methods Added&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>SDK Method</th><th>Rate Limit</th><th>Description</th></tr></thead><tbody><tr><td><code>POST /api/v3/dbs/groups/info</code></td><td><code>getGroupsInfo()</code></td><td>300/min</td><td>Get paid delivery groups</td></tr><tr><td><code>POST /api/v3/dbs/orders/delivery-date</code></td><td><code>getDeliveryDates()</code></td><td>300/min</td><td>Get delivery dates</td></tr><tr><td><code>POST /api/marketplace/v3/dbs/orders/meta/info</code></td><td><code>getMetaBulk()</code></td><td>150/min</td><td>Get metadata (bulk)</td></tr><tr><td><code>POST /api/marketplace/v3/dbs/orders/meta/delete</code></td><td><code>deleteMetaBulk()</code></td><td>150/min</td><td>Delete metadata (bulk)</td></tr><tr><td><code>POST /api/marketplace/v3/dbs/orders/meta/sgtin</code></td><td><code>setSgtinBulk()</code></td><td>500/min</td><td>Set SGTIN (bulk)</td></tr><tr><td><code>POST /api/marketplace/v3/dbs/orders/meta/uin</code></td><td><code>setUinBulk()</code></td><td>500/min</td><td>Set UIN (bulk)</td></tr><tr><td><code>POST /api/marketplace/v3/dbs/orders/meta/imei</code></td><td><code>setImeiBulk()</code></td><td>500/min</td><td>Set IMEI (bulk)</td></tr><tr><td><code>POST /api/marketplace/v3/dbs/orders/meta/gtin</code></td><td><code>setGtinBulk()</code></td><td>500/min</td><td>Set GTIN (bulk)</td></tr><tr><td><code>POST /api/marketplace/v3/dbs/orders/meta/customs-declaration</code></td><td><code>setCustomsDeclarationBulk()</code></td><td>500/min</td><td>Set customs declaration (bulk)</td></tr></tbody></table><h3 id="methods-deprecated-story-26-2" tabindex="-1">Methods Deprecated (Story 26.2) <a class="header-anchor" href="#methods-deprecated-story-26-2" aria-label="Permalink to &quot;Methods Deprecated (Story 26.2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>SDK Method</th><th>Deprecated Endpoint</th><th>Replacement</th></tr></thead><tbody><tr><td><code>getMeta()</code></td><td><code>GET /api/v3/dbs/orders/{orderId}/meta</code></td><td><code>getMetaBulk()</code></td></tr><tr><td><code>deleteMeta()</code></td><td><code>DELETE /api/v3/dbs/orders/{orderId}/meta</code></td><td><code>deleteMetaBulk()</code></td></tr><tr><td><code>setSgtin()</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/sgtin</code></td><td><code>setSgtinBulk()</code></td></tr><tr><td><code>setUin()</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/uin</code></td><td><code>setUinBulk()</code></td></tr><tr><td><code>setImei()</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/imei</code></td><td><code>setImeiBulk()</code></td></tr><tr><td><code>setGtin()</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/gtin</code></td><td><code>setGtinBulk()</code></td></tr><tr><td><code>setCustomsDeclaration()</code></td><td><code>PUT /api/v3/dbs/orders/{orderId}/meta/customs-declaration</code></td><td><code>setCustomsDeclarationBulk()</code></td></tr></tbody></table><p><strong>Total SDK Methods After Epic 26</strong>: 31 (22 existing + 9 new)</p><hr><h2 id="breaking-changes-summary" tabindex="-1">Breaking Changes Summary <a class="header-anchor" href="#breaking-changes-summary" aria-label="Permalink to &quot;Breaking Changes Summary&quot;">​</a></h2><h3 id="what-breaks" tabindex="-1">What Breaks <a class="header-anchor" href="#what-breaks" aria-label="Permalink to &quot;What Breaks&quot;">​</a></h3><ul><li>None -- all changes are additive. Deprecated methods remain functional until April 13, 2026.</li></ul><h3 id="what-does-not-break" tabindex="-1">What Does NOT Break <a class="header-anchor" href="#what-does-not-break" aria-label="Permalink to &quot;What Does NOT Break&quot;">​</a></h3><ul><li>All existing method signatures remain unchanged</li><li>Existing rate limit configuration remains in place</li><li>No type renames or removals</li></ul><h3 id="future-breaking-change-april-13-2026" tabindex="-1">Future Breaking Change (April 13, 2026) <a class="header-anchor" href="#future-breaking-change-april-13-2026" aria-label="Permalink to &quot;Future Breaking Change (April 13, 2026)&quot;">​</a></h3><ul><li>When WB disables deprecated endpoints, the 7 single-order metadata methods will start returning errors</li><li>SDK consumers should migrate to bulk methods before this date</li><li>Consider a major version bump at that time to remove deprecated methods entirely</li></ul><hr><h2 id="risk-assessment" tabindex="-1">Risk Assessment <a class="header-anchor" href="#risk-assessment" aria-label="Permalink to &quot;Risk Assessment&quot;">​</a></h2><h3 id="low-risk" tabindex="-1">Low Risk <a class="header-anchor" href="#low-risk" aria-label="Permalink to &quot;Low Risk&quot;">​</a></h3><ul><li>Info endpoints (Story 26.1) are purely additive with no migration concerns</li><li>Established patterns from Epic 12 status migration apply to metadata migration</li></ul><h3 id="medium-risk" tabindex="-1">Medium Risk <a class="header-anchor" href="#medium-risk" aria-label="Permalink to &quot;Medium Risk&quot;">​</a></h3><ul><li>Bulk metadata methods have different rate limits than the single-order methods they replace (150/min and 500/min vs the incorrect uniform 300/min in current config)</li><li>April 13, 2026 deadline creates time pressure for migration</li></ul><h3 id="mitigation-strategies" tabindex="-1">Mitigation Strategies <a class="header-anchor" href="#mitigation-strategies" aria-label="Permalink to &quot;Mitigation Strategies&quot;">​</a></h3><ul><li>Complete Epic 27 (rate limit audit) before or in parallel to ensure correct rate limit configuration</li><li>Clear <code>@deprecated</code> JSDoc with migration examples reduces user confusion</li><li>Migration guide document with before/after code samples</li></ul><hr><h2 id="backlog-references" tabindex="-1">Backlog References <a class="header-anchor" href="#backlog-references" aria-label="Permalink to &quot;Backlog References&quot;">​</a></h2><ul><li><strong>task-24</strong>: Implementation task for Epic 26</li><li><strong>task-25</strong>: Implementation task for Epic 27 (rate limit audit -- dependency)</li></ul><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The February 2026 swagger update added <code>x-readonly-method</code> and <code>x-category</code> annotations to all 31 DBS operations</li><li>Swagger source was sharded into <code>wildberries_api_doc/04-orders-dbs/</code> directory (4 files) during this update</li><li>The bulk metadata endpoints follow the same pattern as the bulk status endpoints from Epic 12 Story 12.2</li><li>Rate limit tiers for bulk metadata (150/min read, 500/min write) differ from the core DBS tier (300/min) -- this is important context for Epic 27</li></ul>',102)])])}const h=t(a,[["render",i]]);export{u as __pageData,h as default};
